import React, { useState, useEffect } from 'react';

const Settings = ({ token }) => {
  const [activeTab, setActiveTab] = useState('profile');
  const [message, setMessage] = useState(null);

  const [profileData, setProfileData] = useState({
    name: 'Admin User',
    email: 'admin@financeguard.com',
    role: 'System Administrator',
    phone: '',
    department: 'Finance'
  });

  const [emailSettings, setEmailSettings] = useState({
    notifyAnomalies: true,
    notifyReports: true,
    dailyDigest: false,
    alertEmail: '23619232@vistas.ac.in'
  });

  const [securitySettings, setSecuritySettings] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });

  const [systemSettings, setSystemSettings] = useState({
    anomalyThreshold: 800000,
    autoBackup: true,
    dataRetention: 365,
    mlModelActive: true
  });

  useEffect(() => {
    // Load settings from localStorage
    const savedProfile = localStorage.getItem('profileSettings');
    const savedEmail = localStorage.getItem('emailSettings');
    const savedSystem = localStorage.getItem('systemSettings');

    if (savedProfile) setProfileData(JSON.parse(savedProfile));
    if (savedEmail) setEmailSettings(JSON.parse(savedEmail));
    if (savedSystem) setSystemSettings(JSON.parse(savedSystem));
  }, []);

  const handleSaveProfile = () => {
    localStorage.setItem('profileSettings', JSON.stringify(profileData));
    setMessage({ type: 'success', text: 'Profile updated successfully!' });
    setTimeout(() => setMessage(null), 3000);
  };

  const handleSaveEmail = () => {
    localStorage.setItem('emailSettings', JSON.stringify(emailSettings));
    setMessage({ type: 'success', text: 'Email settings updated successfully!' });
    setTimeout(() => setMessage(null), 3000);
  };

  const handleChangePassword = () => {
    if (!securitySettings.currentPassword || !securitySettings.newPassword) {
      setMessage({ type: 'error', text: 'Please fill all password fields' });
      return;
    }
    if (securitySettings.newPassword !== securitySettings.confirmPassword) {
      setMessage({ type: 'error', text: 'New passwords do not match' });
      return;
    }
    if (securitySettings.newPassword.length < 6) {
      setMessage({ type: 'error', text: 'Password must be at least 6 characters' });
      return;
    }

    setMessage({ type: 'success', text: 'Password changed successfully!' });
    setSecuritySettings({ currentPassword: '', newPassword: '', confirmPassword: '' });
    setTimeout(() => setMessage(null), 3000);
  };

  const handleSaveSystem = () => {
    localStorage.setItem('systemSettings', JSON.stringify(systemSettings));
    setMessage({ type: 'success', text: 'System settings updated successfully!' });
    setTimeout(() => setMessage(null), 3000);
  };

  const cardStyle = {
    background: 'rgba(29, 20, 41, 0.6)',
    backdropFilter: 'blur(12px)',
    border: '1px solid rgba(140, 43, 238, 0.1)',
    borderRadius: '0.75rem',
    padding: '2rem',
    marginBottom: '1.5rem'
  };

  const inputStyle = {
    width: '100%',
    padding: '0.75rem',
    background: '#1d1429',
    border: '1px solid #2d2438',
    borderRadius: '0.5rem',
    color: '#f1f5f9',
    fontSize: '0.875rem'
  };

  const labelStyle = {
    display: 'block',
    color: '#cbd5e1',
    marginBottom: '0.5rem',
    fontWeight: '600',
    fontSize: '0.875rem'
  };

  const buttonStyle = {
    padding: '0.75rem 1.5rem',
    background: 'linear-gradient(135deg, #8c2bee 0%, #7c3aed 100%)',
    color: 'white',
    border: 'none',
    borderRadius: '0.5rem',
    fontWeight: '600',
    cursor: 'pointer',
    fontSize: '0.875rem'
  };

  const tabStyle = (isActive) => ({
    padding: '0.75rem 1.5rem',
    background: isActive ? 'rgba(140, 43, 238, 0.2)' : 'transparent',
    border: isActive ? '1px solid #8c2bee' : '1px solid #2d2438',
    borderRadius: '0.5rem',
    color: isActive ? '#8c2bee' : '#cbd5e1',
    cursor: 'pointer',
    fontWeight: '600',
    fontSize: '0.875rem',
    transition: 'all 0.2s'
  });

  return (
    <div style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ color: 'white', fontSize: '2rem', fontWeight: '700', marginBottom: '0.5rem' }}>
          Settings
        </h1>
        <p style={{ color: '#94a3b8' }}>Manage your account and system preferences</p>
      </div>

      {/* Message Alert */}
      {message && (
        <div style={{
          padding: '1rem 1.5rem',
          background: message.type === 'success' ? 'rgba(16, 185, 129, 0.1)' : 'rgba(239, 68, 68, 0.1)',
          border: `1px solid ${message.type === 'success' ? 'rgba(16, 185, 129, 0.2)' : 'rgba(239, 68, 68, 0.2)'}`,
          color: message.type === 'success' ? '#10b981' : '#ef4444',
          borderRadius: '0.5rem',
          marginBottom: '1.5rem',
          fontWeight: '500'
        }}>
          {message.text}
        </div>
      )}

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
        <button onClick={() => setActiveTab('profile')} style={tabStyle(activeTab === 'profile')}>
          Profile
        </button>
        <button onClick={() => setActiveTab('email')} style={tabStyle(activeTab === 'email')}>
          Email Notifications
        </button>
        <button onClick={() => setActiveTab('security')} style={tabStyle(activeTab === 'security')}>
          Security
        </button>
        <button onClick={() => setActiveTab('system')} style={tabStyle(activeTab === 'system')}>
          System
        </button>
      </div>

      {/* Profile Settings */}
      {activeTab === 'profile' && (
        <div style={cardStyle}>
          <h3 style={{ color: 'white', marginBottom: '1.5rem', fontSize: '1.25rem', fontWeight: '600' }}>
            Profile Information
          </h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem' }}>
            <div>
              <label style={labelStyle}>Full Name</label>
              <input
                type="text"
                value={profileData.name}
                onChange={(e) => setProfileData({...profileData, name: e.target.value})}
                style={inputStyle}
              />
            </div>
            <div>
              <label style={labelStyle}>Email Address</label>
              <input
                type="email"
                value={profileData.email}
                onChange={(e) => setProfileData({...profileData, email: e.target.value})}
                style={inputStyle}
              />
            </div>
            <div>
              <label style={labelStyle}>Phone Number</label>
              <input
                type="tel"
                value={profileData.phone}
                onChange={(e) => setProfileData({...profileData, phone: e.target.value})}
                style={inputStyle}
                placeholder="+91 XXXXX XXXXX"
              />
            </div>
            <div>
              <label style={labelStyle}>Department</label>
              <select
                value={profileData.department}
                onChange={(e) => setProfileData({...profileData, department: e.target.value})}
                style={inputStyle}
              >
                <option value="Finance">Finance</option>
                <option value="Accounting">Accounting</option>
                <option value="Audit">Audit</option>
                <option value="Management">Management</option>
              </select>
            </div>
          </div>
          <div style={{ marginTop: '1.5rem' }}>
            <label style={labelStyle}>Role</label>
            <input
              type="text"
              value={profileData.role}
              disabled
              style={{...inputStyle, opacity: 0.6, cursor: 'not-allowed'}}
            />
            <p style={{ color: '#64748b', fontSize: '0.75rem', marginTop: '0.5rem' }}>
              Contact system administrator to change your role
            </p>
          </div>
          <button onClick={handleSaveProfile} style={{...buttonStyle, marginTop: '1.5rem'}}>
            Save Profile
          </button>
        </div>
      )}

      {/* Email Settings */}
      {activeTab === 'email' && (
        <div style={cardStyle}>
          <h3 style={{ color: 'white', marginBottom: '1.5rem', fontSize: '1.25rem', fontWeight: '600' }}>
            Email Notification Preferences
          </h3>
          <div style={{ marginBottom: '1.5rem' }}>
            <label style={labelStyle}>Alert Email Address</label>
            <input
              type="email"
              value={emailSettings.alertEmail}
              onChange={(e) => setEmailSettings({...emailSettings, alertEmail: e.target.value})}
              style={inputStyle}
            />
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: '#cbd5e1', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={emailSettings.notifyAnomalies}
                onChange={(e) => setEmailSettings({...emailSettings, notifyAnomalies: e.target.checked})}
                style={{ width: '1.25rem', height: '1.25rem', cursor: 'pointer' }}
              />
              <div>
                <div style={{ fontWeight: '600' }}>Anomaly Alerts</div>
                <div style={{ fontSize: '0.75rem', color: '#94a3b8' }}>Receive immediate notifications when anomalies are detected</div>
              </div>
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: '#cbd5e1', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={emailSettings.notifyReports}
                onChange={(e) => setEmailSettings({...emailSettings, notifyReports: e.target.checked})}
                style={{ width: '1.25rem', height: '1.25rem', cursor: 'pointer' }}
              />
              <div>
                <div style={{ fontWeight: '600' }}>Report Generation</div>
                <div style={{ fontSize: '0.75rem', color: '#94a3b8' }}>Get notified when reports are generated</div>
              </div>
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: '#cbd5e1', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={emailSettings.dailyDigest}
                onChange={(e) => setEmailSettings({...emailSettings, dailyDigest: e.target.checked})}
                style={{ width: '1.25rem', height: '1.25rem', cursor: 'pointer' }}
              />
              <div>
                <div style={{ fontWeight: '600' }}>Daily Digest</div>
                <div style={{ fontSize: '0.75rem', color: '#94a3b8' }}>Receive a daily summary of all transactions</div>
              </div>
            </label>
          </div>
          <button onClick={handleSaveEmail} style={{...buttonStyle, marginTop: '1.5rem'}}>
            Save Email Settings
          </button>
        </div>
      )}

      {/* Security Settings */}
      {activeTab === 'security' && (
        <div style={cardStyle}>
          <h3 style={{ color: 'white', marginBottom: '1.5rem', fontSize: '1.25rem', fontWeight: '600' }}>
            Change Password
          </h3>
          <div style={{ maxWidth: '500px' }}>
            <div style={{ marginBottom: '1.5rem' }}>
              <label style={labelStyle}>Current Password</label>
              <input
                type="password"
                value={securitySettings.currentPassword}
                onChange={(e) => setSecuritySettings({...securitySettings, currentPassword: e.target.value})}
                style={inputStyle}
              />
            </div>
            <div style={{ marginBottom: '1.5rem' }}>
              <label style={labelStyle}>New Password</label>
              <input
                type="password"
                value={securitySettings.newPassword}
                onChange={(e) => setSecuritySettings({...securitySettings, newPassword: e.target.value})}
                style={inputStyle}
              />
            </div>
            <div style={{ marginBottom: '1.5rem' }}>
              <label style={labelStyle}>Confirm New Password</label>
              <input
                type="password"
                value={securitySettings.confirmPassword}
                onChange={(e) => setSecuritySettings({...securitySettings, confirmPassword: e.target.value})}
                style={inputStyle}
              />
            </div>
            <button onClick={handleChangePassword} style={buttonStyle}>
              Change Password
            </button>
          </div>

          <div style={{ marginTop: '2rem', padding: '1rem', background: 'rgba(140, 43, 238, 0.1)', borderRadius: '0.5rem', border: '1px solid rgba(140, 43, 238, 0.2)' }}>
            <h4 style={{ color: '#8c2bee', marginBottom: '0.5rem', fontSize: '0.875rem', fontWeight: '600' }}>
              Password Requirements
            </h4>
            <ul style={{ color: '#94a3b8', fontSize: '0.75rem', marginLeft: '1.5rem' }}>
              <li>Minimum 6 characters</li>
              <li>Include uppercase and lowercase letters</li>
              <li>Include at least one number</li>
              <li>Avoid common passwords</li>
            </ul>
          </div>
        </div>
      )}

      {/* System Settings */}
      {activeTab === 'system' && (
        <div style={cardStyle}>
          <h3 style={{ color: 'white', marginBottom: '1.5rem', fontSize: '1.25rem', fontWeight: '600' }}>
            System Configuration
          </h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem' }}>
            <div>
              <label style={labelStyle}>Anomaly Threshold (₹)</label>
              <input
                type="number"
                value={systemSettings.anomalyThreshold}
                onChange={(e) => setSystemSettings({...systemSettings, anomalyThreshold: parseInt(e.target.value)})}
                style={inputStyle}
              />
              <p style={{ color: '#64748b', fontSize: '0.75rem', marginTop: '0.5rem' }}>
                Transactions above this amount will be flagged for review
              </p>
            </div>
            <div>
              <label style={labelStyle}>Data Retention (Days)</label>
              <input
                type="number"
                value={systemSettings.dataRetention}
                onChange={(e) => setSystemSettings({...systemSettings, dataRetention: parseInt(e.target.value)})}
                style={inputStyle}
              />
              <p style={{ color: '#64748b', fontSize: '0.75rem', marginTop: '0.5rem' }}>
                Number of days to retain transaction data
              </p>
            </div>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', marginTop: '1.5rem' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: '#cbd5e1', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={systemSettings.autoBackup}
                onChange={(e) => setSystemSettings({...systemSettings, autoBackup: e.target.checked})}
                style={{ width: '1.25rem', height: '1.25rem', cursor: 'pointer' }}
              />
              <div>
                <div style={{ fontWeight: '600' }}>Automatic Backup</div>
                <div style={{ fontSize: '0.75rem', color: '#94a3b8' }}>Enable daily automatic database backups</div>
              </div>
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: '#cbd5e1', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={systemSettings.mlModelActive}
                onChange={(e) => setSystemSettings({...systemSettings, mlModelActive: e.target.checked})}
                style={{ width: '1.25rem', height: '1.25rem', cursor: 'pointer' }}
              />
              <div>
                <div style={{ fontWeight: '600' }}>ML Model Detection</div>
                <div style={{ fontSize: '0.75rem', color: '#94a3b8' }}>Use machine learning for anomaly detection</div>
              </div>
            </label>
          </div>

          <button onClick={handleSaveSystem} style={{...buttonStyle, marginTop: '1.5rem'}}>
            Save System Settings
          </button>
        </div>
      )}
    </div>
  );
};

export default Settings;
